def norm(pts):
    mr=min(pt[0] for pt in pts); mc=min(pt[1] for pt in pts)
    return frozenset((r-mr,c-mc) for r,c in pts)
def variants(fset):
    def ro(p): return frozenset((y,x) for x,y in p)
    def fl(p): return frozenset((-x,y) for x,y in p)
    out={fset}
    curr=fset
    for _ in range(3):
        out|=variants([fl(ro(curr))]) if False else {ro(fl(ro(curr)))}
        out|=variants({fl(curr)}) if False else {fl(curr)}
        curr=ro(fl(ro(curr)))
    return set(out)|{frozenset((y,-x) for x,y in fset)}|{frozenset((-y,-x) for x,y in fset)|frozenset()}
