                    oy=[sum(r) for r in outm]; om=[sum(r) for r in mm]
                    if oy==om:
                        # allow extra cells with color==bg? count exact match of 1s
                        ok = sum(1 for a,b in zip(mm,outm) for A,B in zip(a,b) if A==B and B==1)==sum(mm)
