from collections import Counter
def comps_of(grid,bg):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and (i,j) not in seen:
                col=grid[i][j]; cells=[(i,j)]; seen.add((i,j)); st=[(i,j)]
                while st:
                    a,b=st.pop()
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            na,nb=a+da,b+db
                            if 0<=na<h and 0<=nb<w and (na,nb) not in seen and grid[na][nb]==col:
                                seen.add((na,nb)); cells.append((na,nb)); st.append((na,nb))
                out.append((col,cells))
    return out
def solve(inp):
    cnt=Counter(x for r in inp for x in r); bg=cnt.most_common(1)[0][0]
    cs=comps_of(inp,bg)
    # largest single component overall (any color), tie: most cells
    best=max(cs,key=lambda c:len(c[1]))
    col=best[0]; cells=best[1]
    y0=min(a for a,b in cells); x0=min(b for a,b in cells)
    y1=max(a for a,b in cells); x1=max(b for a,b in cells)
    Y,X=y1-y0+1,x1-x0+1
    return [[col if (a+y0,b+x0) in cells else bg for b in range(X)] for a in range(Y)]
